activities.solution:
function pasosTriangulares(n) {
  let pasos = 0;
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < i; j++) {
      pasos++;
    }
  }
  return pasos;
}
function pasosDuplicando(n) {
  let pasos = 0;
  for (let i = 1; i < n; i *= 2) {
    pasos++;
  }
  return pasos;
}

function pasosTotales(n) {
  let lineal = 0;
  for (let i = 0; i < n; i++) {
    lineal++;
  }
  return lineal + pasosTriangulares(n) + pasosDuplicando(n);
}
